// The highest band a part of that quality scale can come out of, 0..7:
// its roll reaches 1000 times the scale at the most
inline int topQualityBand(float qualityScale) {
    const int reach = (int)(1000.0f * qualityScale + 0.5f);
    for (int band = 7; band > 0; band--) {
        if (reach >= QUALITY_BAND_EDGES[band]) return band;
    }
    return 0;
}

// ...and the lowest: its roll is never under rollLeast
inline int lowestQualityBand(const RockPart& part) {
    const int least = (int)(part.rollLeast * part.qualityScale);
    for (int band = 7; band > 0; band--) {
        if (least >= QUALITY_BAND_EDGES[band]) return band;
    }
    return 0;
}

